calc(1,r'\sum_{n=0}^\infty c_n(x-a)^n','멱급수를 정의하고 식의 각 요소를 설명하라.','Define a power series and explain its components.',[r'a\text{ is the center},\quad c_n\text{ are fixed coefficients}',r'c_0+c_1(x-a)+c_2(x-a)^2+\cdots'],r'\text{an infinite series in nonnegative integer powers of }x-a')
calc(2,r'\sum_{n=0}^\infty c_n(x-a)^n','(a) 수렴 반지름과 계산 방법 (b) 수렴 구간과 계산 방법을 설명하라.','Explain (a) the radius of convergence and its computation and (b) the interval of convergence and its computation.',[r'|x-a|<R:\text{ absolute convergence};\quad|x-a|>R:\text{ divergence}',r'R=1/\limsup\sqrt[n]{|c_n|};\quad R=\lim|c_n/c_{n+1}|\text{ when this limit exists}',r'\text{test }x=a-R\text{ and }x=a+R\text{ separately if }0<R<\infty'],r'\text{interior }(a-R,a+R)\text{ plus whichever endpoints converge}','반지름은 영 또는 무한대도 가능하다. 반지름이 영이면 중심에서만 수렴하며, 무한대이면 모든 실수에서 수렴한다.','The radius may be zero or infinity: radius zero leaves only the center, and infinite radius gives all real inputs.',sub='ab')
rows=[(3,r'x^n/n',1,r'|x|',r'1',r'[-1,1)',[r'x=-1:\sum(-1)^n/n\text{ converges};\quad x=1:\sum1/n\text{ diverges}']),(4,r'(-1)^nnx^n',1,r'|x|',r'1',r'(-1,1)',[r'x=\pm1:\quad|a_n|=n\not\to0']),(5,r'\sqrt n\,x^n',1,r'|x|',r'1',r'(-1,1)',[r'x=\pm1:\quad|a_n|=\sqrt n\not\to0']),(6,r'(-1)^nx^n/\sqrt[3]n',1,r'|x|',r'1',r'(-1,1]',[r'x=-1:\sum n^{-1/3}\text{ diverges};\quad x=1:\sum(-1)^nn^{-1/3}\text{ converges}']),(7,r'nx^n/5^n',1,r'|x|/5',r'5',r'(-5,5)',[r'x=\pm5:\quad|a_n|=n\not\to0']),(8,r'5^nx^n/n',2,r'5|x|',r'1/5',r'[-1/5,1/5)',[r'x=-1/5:\sum(-1)^n/n\text{ converges};\quad x=1/5:\sum1/n\text{ diverges}']),(9,r'x^n/(n3^n)',1,r'|x|/3',r'3',r'[-3,3)',[r'x=-3:\sum(-1)^n/n\text{ converges};\quad x=3:\sum1/n\text{ diverges}']),(10,r'nx^n/(n+1)',1,r'|x|',r'1',r'(-1,1)',[r'x=\pm1:\quad|a_n|=n/(n+1)\to1\ne0']),(11,r'x^n/(2n-1)',1,r'|x|',r'1',r'[-1,1)',[r'x=-1:\sum(-1)^n/(2n-1)\text{ converges};\quad x=1:\sum1/(2n-1)\text{ diverges}']),(12,r'(-1)^nx^n/n^2',1,r'|x|',r'1',r'[-1,1]',[r'x=\pm1:\quad\sum|a_n|=\sum1/n^2<\infty']),(13,r'x^n/n!',0,r'0\quad\text{for every fixed }x',r'\infty',r'\mathbb R',[r'|a_{n+1}/a_n|=|x|/(n+1)\to0']),(14,r'n^nx^n',1,r'+\infty\quad(x\ne0)',r'0',r'\{0\}',[r'\sqrt[n]{|a_n|}=n|x|\to\infty\ (x\ne0);\quad x=0:\sum0=0']),(15,r'x^n/(n^44^n)',1,r'|x|/4',r'4',r'[-4,4]',[r'x=\pm4:\quad\sum|a_n|=\sum1/n^4<\infty']),(16,r'2^nn^2x^n',1,r'2|x|',r'1/2',r'(-1/2,1/2)',[r'x=\pm1/2:\quad|a_n|=n^2\not\to0']),(17,r'(-1)^n4^nx^n/\sqrt n',1,r'4|x|',r'1/4',r'(-1/4,1/4]',[r'x=-1/4:\sum n^{-1/2}\text{ diverges};\quad x=1/4:\sum(-1)^nn^{-1/2}\text{ converges}']),(18,r'(-1)^{n-1}x^n/(n5^n)',1,r'|x|/5',r'5',r'(-5,5]',[r'x=-5:\sum-1/n\text{ diverges};\quad x=5:\sum(-1)^{n-1}/n\text{ converges}']),(19,r'nx^n/[2^n(n^2+1)]',1,r'|x|/2',r'2',r'[-2,2)',[r'x=-2:\sum(-1)^nn/(n^2+1)\text{ converges}',r'x=2:\lim[n/(n^2+1)]/(1/n)=1\Rightarrow\text{divergence}']),(20,r'x^{2n}/n!',1,r'0\quad\text{for every fixed }x',r'\infty',r'\mathbb R',[r'|a_{n+1}/a_n|=x^2/(n+1)\to0']),(21,r'(x-2)^n/(n^2+1)',0,r'|x-2|',r'1',r'[1,3]',[r'x=1,3:\quad\sum|a_n|=\sum1/(n^2+1)<\infty']),(22,r'(-1)^n(x-1)^n/[(2n-1)2^n]',1,r'|x-1|/2',r'2',r'(-1,3]',[r'x=-1:\sum1/(2n-1)\text{ diverges};\quad x=3:\sum(-1)^n/(2n-1)\text{ converges}']),(23,r'(x+2)^n/(2^n\ln n)',2,r'|x+2|/2',r'2',r'[-4,0)',[r'x=-4:\sum(-1)^n/\ln n\text{ converges};\quad x=0:\sum1/\ln n\text{ diverges}']),(24,r'\sqrt n(x+6)^n/8^n',1,r'|x+6|/8',r'8',r'(-14,2)',[r'x=-14,2:\quad|a_n|=\sqrt n\not\to0']),(25,r'(x-2)^n/n^n',1,r'0\quad\text{for every fixed }x',r'\infty',r'\mathbb R',[r'\sqrt[n]{|a_n|}=|x-2|/n\to0']),(26,r'(2x-1)^n/(5^n\sqrt n)',1,r'|2x-1|/5',r'5/2',r'[-2,3)',[r'|2x-1|<5\iff-2<x<3',r'x=-2:\sum(-1)^n/\sqrt n\text{ converges};\quad x=3:\sum1/\sqrt n\text{ diverges}']),(27,r'(\ln n)x^n/n',4,r'|x|',r'1',r'[-1,1)',[r'x=-1:\quad\ln n/n\downarrow0\ (n\ge4)\Rightarrow\text{alternating convergence}',r'x=1:\quad\ln n/n\ge1/n\ (n\ge4)\Rightarrow\text{divergence}']),(28,r'(-1)^nx^n/(n\ln n)',2,r'|x|',r'1',r'(-1,1]',[r'x=-1:\sum1/(n\ln n)\text{ diverges};\quad x=1:\sum(-1)^n/(n\ln n)\text{ converges}']),(29,r'n(x-a)^n/b^n,\quad b>0',1,r'|x-a|/b',r'b',r'(a-b,a+b)',[r'x=a\pm b:\quad|a_n|=n\not\to0']),(30,r'b^n(x-a)^n/\ln n,\quad b>0',2,r'b|x-a|',r'1/b',r'[a-1/b,a+1/b)',[r'x=a-1/b:\sum(-1)^n/\ln n\text{ converges}',r'x=a+1/b:\sum1/\ln n\text{ diverges}']),(31,r'n!(2x-1)^n',1,r'+\infty\quad(x\ne1/2)',r'0',r'\{1/2\}',[r'|a_{n+1}/a_n|=(n+1)|2x-1|\to\infty\quad(x\ne1/2)',r'x=1/2:\quad a_n=0']),(32,r'n^2x^n/[2\cdot4\cdot6\cdots(2n)]',1,r'0\quad\text{for every fixed }x',r'\infty',r'\mathbb R',[r'2\cdot4\cdots(2n)=2^nn!',r'|a_{n+1}/a_n|=|x|(n+1)/(2n^2)\to0']),(33,r'(5x-4)^n/n^3',1,r'|5x-4|',r'1/5',r'[3/5,1]',[r'|5x-4|<1\iff3/5<x<1',r'x=3/5,1:\quad\sum|a_n|=\sum1/n^3<\infty']),(34,r'x^{2n}/[n(\ln n)^2]',2,r'x^2',r'1',r'[-1,1]',[r'x=\pm1:\quad\sum1/[n(\ln n)^2]\text{ converges by the Integral Test}']),(35,r'x^n/[1\cdot3\cdot5\cdots(2n-1)]',1,r'0\quad\text{for every fixed }x',r'\infty',r'\mathbb R',[r'|a_{n+1}/a_n|=|x|/(2n+1)\to0']),(36,r'n!x^n/[1\cdot3\cdot5\cdots(2n-1)]',1,r'|x|/2',r'2',r'(-2,2)',[r'|a_{n+1}/a_n|=(n+1)|x|/(2n+1)\to|x|/2',r'x=\pm2:\quad b_{n+1}/b_n=2(n+1)/(2n+1)>1,\quad b_1=2\Rightarrow b_n\not\to0'])]
for q,term,start,L,R,interval,ends in rows:
 calc(q,rf'\sum_{{n={start}}}^\infty {term}','수렴 반지름과 수렴 구간을 구하라.','Find the radius and interval of convergence.',[rf'\text{{Ratio or root limit}}:\quad L(x)={L}',r'L(x)<1\Rightarrow\text{absolute convergence};\quad L(x)>1\Rightarrow\text{divergence}']+ends,rf'R={R},\quad I={interval}','반지름은 중심으로부터의 거리이다. 유한한 양끝점은 원래 급수에 따로 대입해 판정한다.','The radius measures distance from the center. Test each finite endpoint by substitution into the original series.')
calc(37,r'\sum_{n=0}^\infty c_n4^n\text{ converges}','(a) 입력 음의 이 (b) 입력 음의 사에서도 수렴한다고 결론낼 수 있는지 설명하라.','Decide whether convergence follows at (a) negative two and (b) negative four.',[r'\text{(a)} |-2|<4\Rightarrow\text{absolute convergence}',r'\text{(b)} c_n=(-1)^n/[4^n(n+1)]:\quad\sum c_n4^n\text{ converges},\quad\sum c_n(-4)^n\text{ diverges}',r'c_n=1/[4^n(n+1)^2]\Rightarrow\text{both endpoints converge}'],r'\text{(a) yes; (b) cannot conclude}',sub='ab')
calc(38,r'\sum c_nx^n\text{ converges at }x=-4\text{ and diverges at }x=6','입력이 각각 (a) 일 (b) 팔 (c) 음의 삼 (d) 음의 구인 급수를 판정하라.','Determine the behavior at inputs (a) one, (b) eight, (c) negative three, and (d) negative nine.',[r'4\le R\le6',r'|1|,|-3|<4\Rightarrow\text{absolute convergence}',r'|8|,|-9|>6\Rightarrow\text{divergence}'],r'\text{(a),(c) convergent; (b),(d) divergent}',sub='abcd')
calc(39,r'\sum_{n=0}^\infty\frac{(n!)^k}{(kn)!}x^n,\quad k\in\mathbb N','수렴 반지름을 구하라.','Find the radius of convergence.',[r'|a_{n+1}/a_n|=|x|\frac{(n+1)^k}{(kn+1)\cdots(kn+k)}\to|x|/k^k'],r'R=k^k')
calc(40,r'p<q','수렴 구간이 (a) 양끝 열린 구간 (b) 오른쪽만 닫힌 구간 (c) 왼쪽만 닫힌 구간 (d) 양끝 닫힌 구간인 멱급수를 각각 만들어라.','Construct power series on the interval with endpoints given: (a) both open, (b) only the right closed, (c) only the left closed, and (d) both closed.',[r'a=(p+q)/2,\quad h=(q-p)/2>0,\quad t=(x-a)/h',r'|t|<1\iff p<x<q',r'\sum t^n\text{ diverges at }t=\pm1',r'\sum(-1)^{n-1}t^n/n\text{ converges only at }t=1',r'\sum t^n/n\text{ converges only at }t=-1',r'\sum t^n/n^2\text{ converges at both endpoints}'],r'\text{(a)}\sum_{n=1}^\infty t^n;\quad\text{(b)}\sum_{n=1}^\infty(-1)^{n-1}t^n/n;\quad\text{(c)}\sum_{n=1}^\infty t^n/n;\quad\text{(d)}\sum_{n=1}^\infty t^n/n^2',sub='abcd')
calc(41,r'I=[0,\infty)','이 수렴 구간을 갖는 실수 중심의 멱급수가 존재할 수 있는지 설명하라.','Explain whether a power series with a real center can have this interval of convergence.',[r'\text{unbounded convergence interval}\Rightarrow R=\infty',r'R=\infty\Rightarrow I=\mathbb R'],r'\text{no}','수렴 구간의 내부는 항상 중심에 대해 대칭이다. 한쪽만 무한한 구간은 불가능하다.','The interior of a power-series convergence interval is symmetric about its center, so it cannot be infinite in only one direction.')
calc(42,r'\sum_{n=0}^\infty x^n,\quad f(x)=1/(1-x)','여러 부분합과 합함수를 같은 그림에 그리고 부분합이 합함수로 수렴하는 구간을 확인하라.','Plot several partial sums together with the sum function and identify where they converge to it.',[r's_N(x)=\sum_{n=0}^Nx^n=(1-x^{N+1})/(1-x)\quad(x\ne1)',r'f(x)-s_N(x)=x^{N+1}/(1-x)\to0\quad(|x|<1)',r'x=1:\ s_N=N+1;\quad x=-1:\ s_N=1,0,1,0,\ldots'],r'-1<x<1','구간 밖에서는 일반항이 영으로 가지 않는다. 그림의 유한 부분합은 수렴을 제안하고 나머지 공식이 이를 증명한다.','Outside the interval the terms fail to vanish. The finite plot suggests convergence and the remainder formula proves it.')
calc(43,r'\lim\sqrt[n]{|c_n|}=c\ne0','근 판정법으로 수렴 반지름 공식을 증명하라.','Prove the radius formula using the Root Test.',[r'c>0,\quad\sqrt[n]{|c_nx^n|}\to c|x|',r'c|x|<1\iff|x|<1/c;\quad c|x|>1\iff|x|>1/c'],r'R=1/c','무한대 극한까지 허용하면 그 경우 반지름은 영이다. 경계의 판정은 이 공식만으로 정해지지 않는다.','If an infinite coefficient-root limit is allowed, the radius is zero. This formula alone does not decide endpoint behavior.')
calc(44,r'c_n\ne0,\quad\rho=\lim|c_n/c_{n+1}|','주어진 극한이 존재하면 중심 이동 멱급수의 수렴 반지름과 같음을 증명하라.','Prove that this limit, when it exists, equals the radius for the centered power series.',[r'0<\rho<\infty:\quad\left|\frac{c_{n+1}(x-a)^{n+1}}{c_n(x-a)^n}\right|\to|x-a|/\rho',r'\rho=0:\quad x\ne a\Rightarrow\text{ratio tends to infinity}',r'\rho=\infty:\quad\text{ratio tends to zero for every fixed }x'],r'R=\rho')
calc(45,r'R_c=2,\quad R_d=3','계수를 더한 멱급수의 수렴 반지름을 구하라.','Find the radius when the two coefficient sequences are added.',[r'|x|<2:\quad\sum c_nx^n,\sum d_nx^n\text{ converge absolutely}\Rightarrow R_{c+d}\ge2',r'R_{c+d}>2\Rightarrow\exists t:\ 2<t<\min\{3,R_{c+d}\}',r'\sum c_nt^n=\sum(c_n+d_n)t^n-\sum d_nt^n\text{ converges, contradicting }R_c=2'],r'R_{c+d}=2')
calc(46,r'\sum c_nx^n\text{ has radius }R','거듭제곱 지수를 두 배로 한 급수의 수렴 반지름을 구하라.','Find the radius after doubling every power exponent.',[r't=x^2,\quad\sum c_nx^{2n}=\sum c_nt^n',r'|t|<R\iff|x|<\sqrt R'],r'R_{\mathrm{new}}=\sqrt R\quad(\sqrt0=0,\ \sqrt\infty=\infty)')
